// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2024, "4-5", [{"author":"А. Ковалёва","question":"Змей Горыныч читает сборник пословиц: «Одна _____ хорошо, а две — лучше». «А у меня ещё лучше!» — обрадовался он. Какое слово нужно поставить вместо пропуска?","choices":["нога","рука","голова","квартира","подруга."],"key":"В","review":["Пословица для Горыныча","Вспомни, чем Змей Горыныч отличается от обычного сказочного героя. У него несколько голов, обычно три.","В пословице «Одна голова хорошо, а две лучше» говорится, что вместе думать легче. Горыныч шутит, потому что у него голов ещё больше."]},{"author":"А. Ковалёва","question":"Какое из этих слов нельзя подставить на место пропуска во фразу <em>_____ трещит</em>?","choices":["<em>мороз</em>","<em>голова</em>","<em>болтун</em>","<em>костёр</em>","<em>ручей</em>."],"key":"Д","review":["Что может трещать","О костре говорят «трещит» из-за звука сухих веток. Выражения «мороз трещит», «голова трещит» и «болтун трещит» тоже употребляются: о сильном холоде, боли и быстрой речи.","Ручей обычно журчит. Из предложенных слов именно «ручей» не сочетается с «трещит» в обычной речи."]},{"author":"Л. Фёдорова","question":"Какой герой получил своё имя или прозвище не по тому признаку, что остальные из названных?","choices":["Мальчик-с-пальчик","Мужичок с ноготок","Золушка","Дюймовочка","все герои получили имена по общему признаку."],"key":"В","review":["Откуда взялись имена","Пальчик, ноготок и дюйм подсказывают размеры. Мальчик-с-пальчик, Мужичок с ноготок и Дюймовочка названы так за маленький рост.","Золушка возилась у очага и пачкалась золой. Её прозвище связано с золой, поэтому оно устроено иначе."]},{"author":"А. Ковалёва","question":"У какого существительного из списка невозможно определить род?","choices":["<em>спицы</em>","<em>улицы</em>","<em>ножницы</em>","<em>страницы</em>","<em>ресницы</em>."],"key":"В","review":["Род существительного","Поставь слова в единственное число: спица, улица, страница, ресница. К каждому можно добавить «моя», это женский род.","Даже один инструмент называют «ножницы». У слова есть только множественное число, поэтому обычного рода у него нет."]},{"author":"А. Сомин","question":"Английское слово cloud значит ‘облако’, а berry — ‘ягода’. Какая из этих ягод называется по-английски cloudberry?","choices":["клюква","клубника","крыжовник","чёрная смородина","морошка"],"key":"Д","review":["Ягода по-английски","У четырёх ягод есть другие английские названия: cranberry — клюква, strawberry — клубника, gooseberry — крыжовник, blackcurrant — чёрная смородина.","Остаётся морошка. Проверь в двуязычном словаре: cloudberry означает именно эту оранжевую ягоду, которая на рисунке состоит из маленьких долек."],"figure":{"options":[{"src":"assets/medvezhonok/2024/4-5-5-1.webp","width":195,"height":109,"pixelWidth":195,"pixelHeight":109,"description":"Клюква"},{"src":"assets/medvezhonok/2024/4-5-5-2.webp","width":114,"height":113,"pixelWidth":114,"pixelHeight":113,"description":"Клубника"},{"src":"assets/medvezhonok/2024/4-5-5-3.webp","width":115,"height":85,"pixelWidth":115,"pixelHeight":85,"description":"Крыжовник"},{"src":"assets/medvezhonok/2024/4-5-5-4.webp","width":261,"height":159,"pixelWidth":261,"pixelHeight":159,"description":"Чёрная смородина"},{"src":"assets/medvezhonok/2024/4-5-5-5.webp","width":110,"height":133,"pixelWidth":110,"pixelHeight":133,"description":"Морошка"}],"onlyPictures":false}},{"author":"Б. Иомдин","question":"Слова <em>боб</em> и <em>заказ</em> обладают достаточно редким свойством. Какое слово им <strong>не</strong> обладает?","choices":["<em>довод</em>","<em>доход</em>","<em>шалаш</em>","<em>потоп</em>","<em>топор</em>."],"key":"Д","review":["Слова «боб» и «заказ»","Прочитай «боб» и «заказ» справа налево. Получаются в точности те же слова. По этому же правилу проверь остальные варианты.","Довод, доход, шалаш и потоп сохраняются. «Топор» справа налево даёт «ропот», поэтому только это слово изменилось."]},{"author":"А. Сомин","question":"<em>Прошло пять _____.</em> У какого из этих слов надо заменить корень, чтобы поставить его на место пропуска?","choices":["<em>час</em>","<em>неделя</em>","<em>месяц</em>","<em>год</em>","<em>век</em>."],"key":"Г","review":["После слова «пять»","Заполни фразу знакомыми формами: пять часов, недель, месяцев, веков. Их корни остались узнаваемыми.","С числом пять о возрасте или сроке говорят «пять лет». Форма «лет» нужна вместо формы с корнем «год-»."]},{"author":"Е. Муравенко","question":"В каком случае от данного слова невозможно образовать уменьшительное существительное с помощью суффикса <em>-к-</em>?","choices":["<em>задача</em>","<em>комната</em>","<em>корзина</em>","<em>лента</em>","<em>ягода</em>."],"key":"Г","review":["Уменьшительные с суффиксом","Образуй небольшие названия: «задачка», «комнатка», «корзинка», «ягодка». В каждом между основой и окончанием появилась К.","Для «лента» получится «ленточка». Здесь к основе «лент-» прибавляется «-очк-», поэтому одного «-к-» для этого слова мало."]},{"author":"А. Пиперски","question":"В какой фразе, скорее всего, не будет читаться цифра 0?","choices":["<em>«Спартак» обыграл «Динамо» со счётом 1:0</em>.","<em>В роли Агента 007 снимались очень непохожие друг на друга актёры.</em>","<em>Чтобы вызвать скорую помощь, раньше надо было набирать 03,</em> <em>а теперь существует единая экстренная служба — 112.</em>","<em>Наш самолёт по расписанию должен был вылететь в 04:15</em>.","<em>Запиши мой телефон: 8 (973) 125-03-18.</em>"],"key":"Г","review":["Нули, которые мы читаем","Прочитай вслух счёт «один — ноль», имя агента «ноль-ноль-семь», номер «ноль три» и телефонный номер. Нули нужны, чтобы точно передать числа.","Время 04:15 обычно называют «четыре пятнадцать». Начальный ноль нужен для записи часов двумя цифрами, но при обычном чтении его пропускают."]},{"author":"А. Остроумова","question":"Какое слово значит не то, что остальные?","choices":["<em>величественный</em>","<em>громадный</em>","<em>гигантский</em>","<em>колоссальный</em>","<em>огромный</em>."],"key":"А","review":["Размер или впечатление","Сравни признаки «громадный», «гигантский», «колоссальный» и «огромный». Все четыре подсказывают очень большой размер.","«Величественный» значит «внушающий уважение своим видом». Величественной бывает и осанка человека, даже если он небольшого роста."]},{"author":"А. Пиперски","question":"В книге Марии Даниловой «Аня здесь и там» ребята выбирают имя для животного: «У меня, конечно, было много идей <…>. Например, что-нибудь ироничное: Молния, Стрела или Антилопа». А какому животному они хотят дать имя?","choices":["кошке","собаке","кролику","канарейке","черепахе."],"key":"Д","review":["Имена для питомца","Молния очень быстрая, стрела летит стремительно, антилопа быстро бегает. Все три клички намекают на скорость.","Если так назвать медлительную черепаху, получится шутка. Кличка говорит о быстроте, а питомец движется медленно."]},{"author":"Е. Муравенко","question":"Даны слова: <em>лось, морс, сало, сук, сыр</em>. В скольких из них можно заменить букву <strong>с</strong> буквой <strong>ж</strong> и получить новое слово?","choices":["во всех пяти","в четырёх","в трёх","в двух","в одном."],"key":"Б","review":["Новые слова с Ж","Мысленно замени только С: «лось» → «ложь», «морс» → «морж», «сало» → «жало», «сук» → «жук».","Из «сыр» вышло бы «жыр». Для слова «жир» нужна вторая замена, а менять можно одну букву. Получились четыре новых слова."]},{"author":"М. Рубинштейн","question":"Перед вами отрывок из стихотворения русского поэта Саши Чёрного:\n<em>Вырос снег копной мохнатой,\nГриша бегает кругом,\nТо бока побьёт лопатой,\nТо, пыхтя, катает ком...\nФу, устал. Ещё немножко!\nБрови — два пучка овса,\nГлазки — угли, нос — картошка,\nА из ёлки — волоса.</em>\nА как называется это стихотворение?","choices":["«Снежный человек»","«Снежный дед»","«Снежная бабка»","«Снежная баба»","«Снежная зима»."],"key":"Г","review":["Что лепит Гриша","Гриша катает снежный ком и делает снежной фигуре глаза из углей, нос из картошки, брови из овса и волосы из ёлки.","В следующих строках поэт восклицает «Вот так баба!». Так он называет сделанную из снега фигуру, и заголовок стихотворения — «Снежная баба»."]},{"author":"Е. Муравенко","question":"Во всех словах, кроме одного, можно заменить первую букву другой буквой так, чтобы получились названия птиц. В каком случае это не удаётся сделать?","choices":["<em>врач</em>","<em>капля</em>","<em>корона</em>","<em>лист</em>","<em>ветка</em>."],"key":"Д","review":["Птицы из знакомых слов","Оставь все буквы, кроме первой: «врач» станет «грач», «капля» — «цапля», «корона» — «ворона», «лист» — «аист».","Если убрать первую букву слова «ветка», останется «етка». Названия птицы с таким концом не получается."]},{"author":"Е. Муравенко","question":"В какой паре слов представлены существительные разного рода?","choices":["<em>пригорки — горки</em>","<em>заметки — метки</em>","<em>прослойки — слойки</em>","<em>раскраски — краски</em>","<em>упряжки — пряжки</em>."],"key":"А","review":["Род в паре слов","Назови по одному предмету: заметка — метка, прослойка — слойка, раскраска — краска, упряжка — пряжка. Все эти слова женского рода.","Говорят «мой пригорок», но «моя горка». Только у «пригорков» и «горок» в единственном числе род разный."]},{"author":"А. Пиперски","question":"Как обычно не говорят?","choices":["<em>без десяти девять</em>","<em>без десяти десять</em>","<em>без десяти одиннадцать</em>","<em>без десяти двенадцать</em>","<em>без десяти тринадцать</em>."],"key":"Д","review":["Десять минут до часа","Фраза «без десяти» означает, что до названного часа осталось десять минут. В обычной речи так называют часы от одного до двенадцати.","В 12:50 обычно говорят «без десяти час», потому что скоро час дня. Поэтому «без десяти тринадцать» — непривычная форма."]},{"author":"И. Рубанов","question":"В следующую среду в нашу область __________ холодов.\nКак <strong>не</strong> следует заполнять пробел?","choices":["<em>вернётся волна</em>","<em>вернётся новая волна</em>","<em>придёт волна</em>","<em>придёт новая волна</em>","все варианты (А)–(Г) подходят."],"key":"Б","review":["Волна холодов","Сравни глаголы. «Придёт» просто означает, что начнётся похолодание. «Вернётся» говорит о том, что похолодание уже было и появилось снова.","По прогнозу «новая волна» ещё только появится. О ней говорят «придёт новая волна», а сочетание «вернётся новая волна» смешивает два смысла."]},{"author":"Е. Муравенко","question":"Вставьте пропущенные буквы в слова: <em>ко_есо</em>, <em>кр_вать</em>, <em>рю_зак</em>, <em>ст_кан</em>, <em>сугро_</em>. Какое слово можно получить из вставленных букв?","choices":["<em>балка</em>","<em>бокал</em>","<em>галоп</em>","<em>палка</em>","<em>полка</em>."],"key":"Б","review":["Пять вставленных букв","Заполни пропуски: «колесо», «кровать», «рюкзак», «стакан», «сугроб». Вставленные буквы — Л, О, К, А, Б.","Переставь их в порядок Б, О, К, А, Л. Из всех пяти букв складывается «бокал»."]},{"author":"О. Подлесская","question":"<em>Королева подарила принцессе флакон</em> _____.","choices":["<em>супа</em>","<em>компота</em>","<em>сахара</em>","<em>булавок</em>","<em>духов</em>."],"key":"Д","review":["Подарок во флаконе","Флакон — небольшой сосуд, обычно с узким горлышком. Суп и компот обычно наливают в другую посуду, а сахар и булавки во флаконе не дарят.","Духи выпускают в небольших флаконах. Привычное сочетание — «флакон духов»."]},{"author":"О. Подлесская","question":"В каком примере глагол <em>уступать</em> означает не то, что в других?","choices":["<em>Эмилю было пять лет от роду, но силой он не уступал молодому бычку.</em> (А. Линдгрен)","<em>Он никогда никому не уступал дороги на улице</em> — <em>наоборот,</em> <em>норовил толкнуть каждого встречного…</em> (Н. Носов)","<em>Альфред не уступал хозяину в прилежании и сам штопал свои носки.</em> (А. Линдгрен)","<em>Она не уступала сестре красотой, бирюзовая мантия очень ей шла.</em> (Дж. Роулинг)","<em>За ним гнались всего трое дикарей, но они заметно уступали беглецу</em> <em>в скорости.</em> (Д. Дефо)"],"key":"Б","review":["Два значения «уступать»","В четырёх отрывках сравнивают силу, прилежание, красоту или скорость. «Уступать» там значит «быть слабее» или «быть хуже в чём-то».","«Уступить дорогу» означает дать другому пройти или проехать. Это другое значение, поэтому подходит фраза про прохожих."]},{"author":"А. Пиперски","question":"То, что загадано в этом ребусе, обычно бывает:","choices":["у собак","у кошек","у лошадей","у голубей","у рыб."],"key":"В","review":["Буквы в ребусе","Маленькая О стоит внутри А. Скажи это словами, сохраняя предлог: «О в А». В ребусе получается «ова».","Эта группа стоит под буквой К. Прочитай «под К» и «ова»: получается «подкова». Подковы бывают у лошадей."],"figure":{"condition":{"src":"assets/medvezhonok/2024/4-5-21.webp","width":245,"height":251,"pixelWidth":245,"pixelHeight":251,"alt":"Красная К над синей А, внутри которой маленькая О."}}},{"author":"И. Рубанов","question":"Про очень жадного человека говорят, что <em>у него зимой _____ не выпросишь</em>. Что пропущено в этой фразе?","choices":["<em>денег</em>","<em>дров</em>","<em>снега</em>","<em>хлеба</em>","<em>шубы</em>."],"key":"В","review":["Поговорка о жадности","Найди то, чего зимой обычно очень много и что можно попросить совсем без затрат. Это подчёркивает жадность человека.","В устойчивом выражении говорят «у него зимой снега не выпросишь». Даже снега он не даст, хотя снег легко найти."]},{"author":"П. Долгополов","question":"Какое из следующих слов произносится по-разному в зависимости от значения?","choices":["<em>глазки</em>","<em>волосики</em>","<em>ножки</em>","<em>ручки</em>","<em>ноготки</em>."],"key":"А","review":["Произношение слова","Сравни «гла́зки» ребёнка и «глазки́» на картофелине. В первом случае речь о маленьких глазах, во втором — о местах, откуда растут побеги.","Проверь, куда падает ударение: в первом смысле на А, во втором на И. Это одно написание с двумя произношениями."]},{"author":"Е. Муравенко","question":"Сколько раз в этих строчках из сказки «Конёк-Горбунок» П. П. Ершова встречается твёрдый звук [в]?\n<em>Караульщик помолился,\nВправо, влево поклонился\nИ сквозь зубы отвечал:\n«Всю я ноченьку не спал».</em>","choices":["три","четыре","пять","шесть","семь."],"key":"Б","review":["Твёрдый В в стихах Ершова","В начале «вправо» буква В стоит перед глухим [п], а в «всю» — перед глухим [с’]. В обоих случаях на месте В слышно [ф].","Твёрдый [в] слышится во втором «в» слова «вправо», дважды во «влево» и в слове «сквозь». Всего четыре звука [в]."]},{"author":"А. Ковалёва","question":"Учитель попросил учеников подобрать к словам <em>недруг, неслух</em> и <em>неуч</em> по одному слову, близкому по значению.\nПетя написал: <em>недоброжелатель, строптивый, неучтивый.</em>\nИра написала: <em>знакомый, ослушник, невежда.</em>\nИгорь написал: <em>противник, своевольный, неучтённый.</em>\nЛена написала: <em>неприятель, непослушный, необразованный.</em>\nТоля написал: <em>враг, глухой, недоучка.</em>\nКто выполнил задание правильно?","choices":["Петя","Ира","Игорь","Лена","Толя."],"key":"Г","review":["Три близких по смыслу слова","Проверь смысл каждой тройки. Неуч — необразованный человек, а «неучтивый» означает невежливого, «неучтённый» — пропущенного при подсчёте. «Знакомый» не обязательно недруг, а «глухой» не означает непослушного.","У Лены подходят все три замены: недруг — неприятель, неслух — непослушный, неуч — необразованный. Лена выполнила задание правильно."]},{"author":"А. Сомин","question":"Для обозначения аэропортов в России используются так называемые внутренние коды. Выберите правильный порядок кодов для аэропортов Владивостока, Владикавказа и Владимира.","choices":["ВЛА, ВВО, ВЛМ","ВЛМ, ВЛА, ВВО","ВЛА, ВЛМ, ВВО","ВВО, ВЛА, ВЛМ","ВВО, ВЛМ, ВЛА."],"key":"Г","review":["Как различить коды городов","Сопоставь ВВО со словом «Владивосток»: начальное В и ВО из «восток». У Владимира заметная буква М, которую видим в ВЛМ.","Владикавказу остаётся ВЛА. Проверь порядок городов в условии: Владивосток, Владикавказ, Владимир — ВВО, ВЛА, ВЛМ."]},{"author":"А. Сомин","question":"Одна передача о птицах называется __________.","choices":["«Колю слышал?»","«Витю видел?»","«Саню знаешь?»","«Косте скажешь?»","«Пашу помнишь?»"],"key":"Б","review":["Как называется передача","Прочитай варианты вслух. «Витю видел?» выделяется повтором «ви-ви» и похоже на короткий птичий пересвист.","Так передают песню птицы чечевицы. Авторы передачи о птицах и взяли этот «вопрос» для названия — «Витю видел?»."]},{"author":"Ф. Тучак","question":"В карельском языке много заимствований из русского. Что в людиковском наречии карельского языка значит слово lauk?","choices":["больница","магазин","библиотека","завод","школа."],"key":"Б","review":["Заимствование в карельском","Сравни звучание lauk с русскими словами. Оно напоминает «лавка» — слово, которым называют в том числе небольшой торговый уголок.","Магазин можно назвать лавкой, а для других мест такое слово не используют. В людиковском наречии lauk и означает магазин."]},{"author":"О. Подлесская","question":"Перед вами начала четырёх пословиц: <em>Была бы невеста</em>, <em>Была бы свинка</em>, <em>Было бы</em> <em>корыто</em>, <em>Была бы охота</em>. Найдите среди ответов лишнее продолжение.","choices":["<em>будет и щетинка</em>","<em>а работа найдётся</em>","<em>будет и молочко</em>","<em>а свиньи найдутся</em>","<em>а сваха будет</em>."],"key":"В","review":["Продолжения пословиц","Подбери по смыслу: если есть невеста, будет и сваха, у свинки будет щетинка. Если есть корыто, найдутся свиньи, а если есть охота, отыщется работа.","Все четыре начала получили продолжения. «Будет и молочко» осталось лишним: среди начал нет пословицы о корове."]},{"author":"Б. Иомдин и А. Черипко","question":"Помещение под названием <em>чакалня</em> в Болгарии можно встретить обычно на вокзалах или в аэропортах. А что значит глагол <em>чакам</em>?","choices":["путешествую","жду","ем","пишу","читаю."],"key":"Б","review":["Помещение на вокзале","Представь, чем люди занимаются в специальном зале на вокзале до объявления посадки. Большую часть времени они ждут поезда или самолёта.","Болгарское «чакалня» означает зал ожидания. Поэтому близкий глагол «чакам» переводится «жду»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
